// One singleton instance shared by every request (no real timers/net).
class Greeter {
  setUser(u){ this.currentUser = u; }      // field => shared mutable state
  greet(){ return 'hello ' + this.currentUser; }
}
const svc = new Greeter(); // singleton: created once

// Interleaving: A sets its user, B overwrites the shared field, THEN A reads.
function simulate(){
  svc.setUser('alice');  // request A begins
  svc.setUser('bob');    // request B begins, overwrites the shared field
  const aSees = svc.greet(); // request A reads -> gets bob (leak!)
  const bSees = svc.greet(); // request B reads -> bob
  return [aSees, bSees];
}
const [a, b] = simulate();
console.log(a);
console.log(b);
